1773642385 0.001 30150 0x7aad63bb8b286b8ba07d15417d3fb71ceed411e4be0f700ce2f22bbe08585a3b = BUY
"""

    // MARK: - Decoded capture (test-side owner)

    private struct Trade: Equatable {
        let t: Int
        let pText: String
        let sizeText: String
        let tx: String
        let asset: String
        let action: String
        var p: Double { Double(pText)! }
        var size: Double { Double(sizeText)! }
    }

    private struct Side: Equatable {
        let side: String
        let token: String
        let settled: Bool
        let captured: Bool
        let trades: [Trade]
    }

    private struct Market: Equatable {
        let race: String
        let id: String
        let name: String
        let condition: String
        let sourceResolved: Bool
        let nominee: Bool
        let winner: Bool
        let predicate: String
        let yes: Side
        let no: Side
        var sides: [Side] { [yes, no] }
        func side(_ name: String) -> Side { name == "Yes" ? yes : no }
    }

    private static let cutoff = 1773558000
    private static let picture = "50251"
    private static let actor = "50282"
    private static let titles = ["50251": "Best Picture", "50282": "Best Actor"]
    private static let reportedWinners = ["50251": "One Battle After Another", "50282": "Michael B. Jordan"]
    private static let scope = "ceremony-hub|98th-academy-awards"
    private static let source = "polymarket"
    private static let oba = "613835", sinners = "613837", chalamet = "614008", jordan = "614012", hamnet = "613836"
    private static let shapes: [String: FieldHistoryShape10868] = [
        "613835": .circle, "613837": .diamond, "614008": .square, "614012": .triangle,
    ]
    private static let tints: [String: Color] = ["613835": .blue, "613837": .orange, "614008": .blue, "614012": .orange]

    /// Keyed "<market> <side>". A trade's asset column "=" is that side's
    /// header token, written once; any other value is the asset verbatim.
    private static let trades: [String: [Trade]] = {
        var result: [String: [Trade]] = [:]
        var key = ""
        var token = ""
        for line in Tests.retainedTrades.split(separator: "\n") {
            let field = line.split(separator: " ").map(String.init)
            if line.hasPrefix("@") {
                key = String(field[0].dropFirst()) + " " + field[1]
                token = field[2]
                result[key] = []
                continue
            }
            result[key, default: []].append(Trade(t: Int(field[0])!, pText: field[1], sizeText: field[2], tx: field[3],
                                                  asset: field[4] == "=" ? token : field[4], action: field[5]))
        }
        return result
    }()

    private static let markets: [Market] = Tests.retainedMarkets.split(separator: "\n").map { line in
        let field = line.split(separator: "|", omittingEmptySubsequences: false).map(String.init)
        func side(_ name: String, _ at: Int) -> Side {
            Side(side: name, token: field[at], settled: field[at + 1] == "true", captured: field[at + 2] == "true",
                 trades: Tests.trades["\(field[1]) \(name)"] ?? [])
        }
        return Market(race: field[0], id: field[1], name: field[2], condition: field[3],
                      sourceResolved: field[4] == "true", nominee: field[5] == "true", winner: field[6] == "true",
                      predicate: field[13], yes: side("Yes", 7), no: side("No", 10))
    }

    private static func market(_ id: String) -> Market { markets.first { $0.id == id }! }
    private static func race(_ race: String) -> [Market] { markets.filter { $0.race == race } }
    /// The race's markets with captured history, in source order.
    private static func captured(_ race: String) -> [Market] {
        Tests.race(race).filter { $0.sides.contains(where: \.captured) }
    }
    private static func rules(_ race: String) -> String {
        (race == picture ? retainedRulesPicture : retainedRulesActor).joined(separator: "\n")
    }

    private static func digest(_ text: String) -> String {
        SHA256.hash(data: Data(text.utf8)).map { String(format: "%02x", $0) }.joined()
    }

    /// The approved `probabilityLabel` rule, owner-side.
    private static func pct(_ p: Double) -> String {
        if p == 0 { return "0%" }
        if p == 1 { return "100%" }
        let tenths = (p * 1000).rounded()
        if tenths == 0 { return "<0.1%" }
        if tenths == 1000 { return ">99.9%" }
        return tenths.truncatingRemainder(dividingBy: 10) == 0
            ? "\(Int(tenths / 10))%" : String(format: "%.1f%%", tenths / 10)
    }

    private static let clockFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(identifier: "UTC")
        formatter.dateFormat = "MMM d, yyyy, HH:mm:ss 'UTC'"
        return formatter
    }()

    /// CONSTRUCTED UTC clock words; real binding localizes through the owner's formatter.
    private static func clock(_ t: Int) -> String {
        clockFormatter.string(from: Date(timeIntervalSince1970: TimeInterval(t)))
    }

    /// The owner's before-day reference: the last trade strictly before the cutoff.
    private static func baseline(_ side: Side) -> Trade? { side.trades.last { $0.t < cutoff } }

    // MARK: - Owner originals

    private static func selection(_ m: Market, _ side: String, scope: String = Tests.scope) -> Details.Selection {
        Details.Selection(scope: scope, identity: Details.Identity(source: source, market: m.id, side: side))
    }

    private static func pregame(_ s: Side) -> Details.Reading {
        if let base = baseline(s) {
            return Details.Reading.value(pct(base.p), placement: base.p, provenance: "Before awards day · " + clock(base.t))
        }
        return Details.Reading.missing(s.captured ? "No captured pre-day trade" : "History not captured for this original outcome")
    }

    private static func original(_ m: Market, _ s: Side, _ phase: Phase) -> Details.Original {
        let title = titles[m.race]!
        let final = phase == .final && m.sourceResolved
        return Details.Original(
            identity: Details.Identity(source: source, market: m.id, side: s.side), title: m.name,
            outcome: s.side == "Yes" ? "Yes · wins \(title)" : "No · does not win \(title)",
            mode: final ? .result : .pregame, pregame: pregame(s), later: nil,
            grade: final ? Details.Grade(words: s.settled ? "Happened" : "Didn't happen",
                                         provenance: "Original contract · source resolved") : nil,
            about: Details.About(source: "Polymarket", rules: .verified([m.predicate, rules(m.race)]),
                                 provenance: [Details.Row(label: "Original token", value: s.token),
                                              Details.Row(label: "Condition", value: m.condition)],
                                 historicalQuote: nil),
            beforeLabel: "Before awards day")
    }

    private static func catalogue(_ phase: Phase, scope: String = Tests.scope, dropping: Details.Identity? = nil,
                                  duplicating: Details.Identity? = nil) -> Details.Catalogue {
        var originals: [Details.Original] = []
        for m in markets {
            for s in m.sides {
                let item = original(m, s, phase)
                if item.identity == dropping { continue }
                originals.append(item)
                if item.identity == duplicating { originals.append(item) }
            }
        }
        return Details.Catalogue(scope: scope, originals: originals)
    }

    private static let yTicks = [0.0, 0.5, 1.0].map { FieldHistoryTick10868(value: $0, lines: [Tests.pct($0)]) }
    private static let markKey = FieldHistoryMarkKey10868(hollow: "Outlined: exact before-day reference",
                                                          filled: "Original Yes trade")

    private static func action(_ id: String, _ label: String, available: Bool = true) -> FieldHistoryAction10868 {
        FieldHistoryAction10868(id: id, label: label, spokenLabel: nil, isAvailable: available)
    }

    private static func domain(_ trades: [Trade]) -> FieldHistoryDomain10868 {
        guard let lower = trades.map(\.t).min(), let upper = trades.map(\.t).max() else {
            return FieldHistoryDomain10868(lower: Double(cutoff - 86_400), upper: Double(cutoff))
        }
        return FieldHistoryDomain10868(lower: Double(lower), upper: Double(upper > lower ? upper : lower + 3_600))
    }

    private static func points(_ shown: [Trade], baseline: Trade?) -> [FieldHistoryRun10868] {
        shown.map { trade in
            FieldHistoryRun10868(id: "run-" + trade.tx, points: [
                FieldHistoryPoint10868(id: trade.tx, x: Double(trade.t), probability: trade.p,
                                       style: trade == baseline ? .hollow : .filled),
            ])
        }
    }

    private static func observation(_ trade: Trade) -> FieldHistoryReading10868 {
        FieldHistoryReading10868.observation(pointID: trade.tx, figure: pct(trade.p), provenance: clock(trade.t))
    }

    private static func sideSeriesID(_ m: Market, _ side: String) -> String { "\(m.id)-\(side)" }

    /// One original side's own trades, never another side's and never a complement.
    private static func sideSeries(_ m: Market, _ s: Side, _ phase: Phase) -> FieldHistorySeries10868 {
        let shown = phase != .final ? s.trades.filter { $0.t < cutoff } : s.trades
        let base = baseline(s)
        let before = base.map(observation) ?? FieldHistoryReading10868.absent(
            words: s.captured ? "No captured pre-day trade" : "History not captured for this original outcome")
        let recorded = shown.last.map(observation) ?? FieldHistoryReading10868.absent(words: "No captured trade")
        return FieldHistorySeries10868(
            id: sideSeriesID(m, s.side), name: "\(m.name) · \(s.side)", shape: shapes[m.id] ?? .circle,
            tint: tints[m.id] ?? .gray, runs: points(shown, baseline: base), links: [], labelPointID: nil,
            before: before, recorded: recorded,
            absentWords: s.captured ? nil : "History not captured for this original outcome", choose: nil)
    }

    private static func sideInput(_ m: Market, _ s: Side, _ phase: Phase, mini: Bool,
                                  series override: FieldHistorySeries10868? = nil) -> FieldHistoryInput10868 {
        let series = override ?? sideSeries(m, s, phase)
        let shown = phase != .final ? s.trades.filter { $0.t < cutoff } : s.trades
        return FieldHistoryInput10868(
            title: "\(m.name) · original \(s.side)", caption: nil, series: [series],
            selection: .series(id: series.id, missingWords: "Original unavailable"),
            domain: domain(shown), ceiling: 1, yTicks: yTicks, xTicks: [], guides: [], breaks: [],
            readout: .beforeAndRecorded(beforeLabel: "Before awards day", recordedLabel: "Last recorded"),
            markKey: markKey, comparisonExplanation: nil, notes: ["Only this original \(s.side) token is shown."],
            summary: "\(m.name), original \(s.side) trades, zero to 100%.", plotHeight: mini ? 140 : 320,
            unboundReadingWords: "Not bound to this trade", plotUnavailableWords: nil,
            windows: nil, scale: nil, moreOriginals: nil, details: nil, expand: nil,
            inspect: mini ? nil : action("side.inspect", "Inspect trades"),
            previous: mini ? nil : action("side.previous", "Earlier trade"),
            next: mini ? nil : action("side.next", "Later trade"), inspection: nil,
            layout: mini ? .expanded : .cohortAbove,
            plotAbsence: s.captured ? nil : FieldHistoryPlotAbsence10868(
                title: "No captured history",
                words: "History was not captured for this original outcome; that does not mean it never traded."),
            showsKey: !mini)
    }

    private static func finishWords(_ m: Market) -> String {
        m.winner ? "Winner" : m.nominee ? "Nominee · did not win" : "Not a reported nominee"
    }

    private static func recorded(_ m: Market, _ s: Side, _ phase: Phase) -> Details.RecordedHistory {
        let shown = phase != .final ? s.trades.filter { $0.t < cutoff } : s.trades
        let last: Details.Reading = shown.last.map {
            Details.Reading.value(pct($0.p), placement: $0.p, provenance: "Last recorded · " + clock($0.t))
        } ?? Details.Reading.missing("No captured trade")
        return Details.RecordedHistory(
            selection: selection(m, s.side), mode: original(m, s, phase).mode, seriesID: sideSeriesID(m, s.side),
            availability: "Current probability unavailable · historical records below",
            readings: [Details.RecordedReading(label: "Before awards day", marker: .hollow, reading: pregame(s)),
                       Details.RecordedReading(label: "Last recorded", marker: .solid, reading: last)],
            movement: nil, history: sideInput(m, s, phase, mini: true),
            finishLabel: "Reported award result",
            finish: phase == .final ? .reported(words: finishWords(m), spoken: nil) : nil,
            preview: action("original.preview", "Preview history"),
            expand: action("original.expand", "Full original history"),
            explore: s.captured ? action("original.explore", "Explore original history") : nil,
            unmatchedWords: "Recorded history unavailable for this outcome")
    }

    private static func sideHistory(_ m: Market, _ side: String, _ phase: Phase,
                                    admittedFor: Phase? = nil) -> CeremonySideHistory10868 {
        let s = m.side(side)
        return CeremonySideHistory10868(phase: admittedFor ?? phase, selection: selection(m, side),
                                        seriesID: sideSeriesID(m, side), history: sideInput(m, s, phase, mini: false))
    }

    // MARK: - Owner chooser (bounded six-prop windows)

    private static func chooserScope(_ race: String) -> String { "\(scope)|\(race)" }

    private static func ref(_ m: Market, _ side: String) -> FieldChooserOriginalRef10868 {
        FieldChooserOriginalRef10868(scope: chooserScope(m.race), source: source, marketID: m.id, outcomeID: "\(m.id):\(side)")
    }

    private static func chooser(_ race: String, _ phase: Phase, window: Int? = 0) -> FieldChooserInput10868 {
        let props = Tests.race(race)
        let catalogue: [FieldChooserOriginal10868] = props.flatMap { m in
            m.sides.map { s in
                let base = baseline(s)
                let value: FieldChooserValue10868 = base.map { .recorded(text: pct($0.p), detail: clock($0.t)) }
                    ?? .missing(s.captured ? "No captured pre-day trade" : "History not captured")
                return FieldChooserOriginal10868(
                    ref: ref(m, s.side), name: "\(m.name) · \(s.side)",
                    plan: .single(FieldChooserReading10868(label: "Before awards day", value: value)),
                    preview: FieldChooserPreview10868(history: nil, absence: s.captured
                        ? "Captured history in Details" : "History not captured for this original outcome"),
                    movement: nil, clock: nil,
                    result: phase == .final ? FieldChooserResult10868(title: "Reported award result", words: finishWords(m)) : nil,
                    browseStatus: (m.nominee ? "Reported nominee" : "Not a reported nominee")
                        + (s.captured ? " · history captured" : " · history not captured"))
            }
        }
        let groups: [FieldChooserGroup10868] = stride(from: 0, to: props.count, by: 6).map { start in
            let slice = Array(props[start..<min(start + 6, props.count)])
            return FieldChooserGroup10868(id: "window.\(race).\(start / 6)", label: "\(start + 1)–\(start + slice.count)",
                                          countText: "\(slice.count) props · \(slice.count * 2) originals",
                                          refs: slice.flatMap { m in ["Yes", "No"].map { ref(m, $0) } })
        }
        return FieldChooserInput10868(
            scope: chooserScope(race), intro: nil,
            featured: FieldChooserFeatured10868(title: "In this history", badge: nil,
                                                refs: captured(race).map { ref($0, "Yes") },
                                                emptyWords: "No captured contender"),
            context: "\(props.filter(\.nominee).count) reported nominees; all \(props.count) original candidate props stay reachable.",
            more: nil,
            browse: FieldChooserBrowse10868(
                id: "browse.\(race)", title: "All \(props.count) original props", expanded: true,
                note: "Six props at a time · every Yes and No original stays selectable",
                groupsLabel: "Prop windows", groups: groups,
                selectedGroupID: window.map { "window.\(race).\($0)" },
                noGroupWords: "Choose a window of props", groupUnavailableWords: "That window is not available",
                emptyGroupWords: "No props in this window"),
            catalogue: catalogue, frame: nil, selected: nil,
            unavailableWords: "Original unavailable in this update", chooseHint: "Opens this original's Details")
    }

    private static func originals(_ phase: Phase, held: Details.Selection? = nil, catalogue: Details.Catalogue? = nil,
                                  sideHistory: CeremonySideHistory10868? = nil, chooser: FieldChooserInput10868? = nil,
                                  admittedFor: Phase? = nil) -> CeremonyEventPageOriginals10868 {
        var sides: [CeremonySideChoice10868] = []
        var recorded: Details.RecordedHistory?
        if let held, let m = markets.first(where: { $0.id == held.identity.market }) {
            sides = ["Yes", "No"].map { CeremonySideChoice10868(label: $0, selection: selection(m, $0)) }
            recorded = Tests.recorded(m, m.side(held.identity.side), phase)
        }
        return CeremonyEventPageOriginals10868(
            phase: admittedFor ?? phase, catalogue: catalogue ?? Tests.catalogue(phase), selection: held,
            recorded: recorded, sides: sides, sideHistory: sideHistory, chooser: chooser, tint: .blue)
    }

    /// Every surface's admission at once: chooser, sides, Details, side history.
    private static func fullOriginals(_ phase: Phase, admittedFor: Phase? = nil) -> CeremonyEventPageOriginals10868 {
        let m = market(oba)
        return originals(phase, held: selection(m, "Yes"),
                         sideHistory: sideHistory(m, "Yes", phase, admittedFor: admittedFor ?? phase),
                         chooser: chooser(picture, phase), admittedFor: admittedFor)
    }

    // MARK: - Owner history

    private enum Window: String { case recent, earlier, all }

    private static func categoryHistory(_ race: String, _ phase: Phase, window: Window = .all,
                                        inspecting: [String: String]? = nil,
                                        before overrides: [String: FieldHistoryReading10868] = [:],
                                        recorded recordedOverrides: [String: FieldHistoryReading10868] = [:],
                                        plotHeight: CGFloat = 240) -> FieldHistoryInput10868 {
        func shown(_ s: Side) -> [Trade] {
            if phase != .final { return s.trades.filter { $0.t < cutoff } }
            switch window {
            case .all: return s.trades
            case .earlier: return s.trades.filter { $0.t < cutoff }
            case .recent: return s.trades.filter { $0.t >= cutoff }
            }
        }
        let contenders = captured(race)
        let series: [FieldHistorySeries10868] = contenders.map { m in
            let drawn = shown(m.yes)
            let base = baseline(m.yes)
            let id = sideSeriesID(m, "Yes")
            var before = FieldHistoryReading10868.absent(words: "No captured pre-day trade")
            if let base {
                before = drawn.contains(base) ? observation(base)
                    : .independent(figure: pct(base.p), provenance: "Before awards day · " + clock(base.t))
            }
            var recorded = drawn.last.map(observation) ?? FieldHistoryReading10868.absent(words: "No captured trade in this view")
            if let tx = inspecting?[id], let trade = m.yes.trades.first(where: { $0.tx == tx }) {
                recorded = observation(trade)
            }
            return FieldHistorySeries10868(
                id: id, name: m.name, shape: shapes[m.id]!, tint: tints[m.id]!, runs: points(drawn, baseline: base),
                links: [], labelPointID: nil, before: overrides[id] ?? before, recorded: recordedOverrides[id] ?? recorded,
                absentWords: drawn.isEmpty ? "No captured trade in this view" : nil,
                choose: action("details.\(m.id)", "\(m.name) details"))
        }
        let all = contenders.flatMap { shown($0.yes) }
        let span = domain(all)
        let inspection: FieldHistoryInspection10868? = inspecting.map { held in
            var selections: [String: FieldHistorySelection10868] = [:]
            for m in contenders {
                let id = sideSeriesID(m, "Yes")
                if let tx = held[id], let trade = m.yes.trades.first(where: { $0.tx == tx }) {
                    selections[id] = .point(id: tx, spoken: pct(trade.p))
                } else {
                    selections[id] = .absent(words: "No captured trade at this time")
                }
            }
            return FieldHistoryInspection10868(x: nil, caption: "Recorded trade", selections: selections, choices: [],
                                               choicePresentation: .buttons(groupLabel: "Trades"),
                                               note: "Only exact captured trades are shown.")
        }
        let windows = FieldHistoryWindows10868(groupLabel: "Award history window", choices: [
            FieldHistoryWindowChoice10868(action: action("window.recent", "Recent captures", available: phase == .final),
                                          isSelected: phase == .final && window == .recent),
            FieldHistoryWindowChoice10868(action: action("window.earlier", "Before awards day"),
                                          isSelected: phase != .final || window == .earlier),
            FieldHistoryWindowChoice10868(action: action("window.all", "All captured", available: phase == .final),
                                          isSelected: phase == .final && window == .all),
        ])
        return FieldHistoryInput10868(
            title: "\(titles[race]!) chances",
            caption: phase == .final ? "Last recorded probabilities · separate clocks" : "Before awards day · dated trades",
            series: series, selection: .none, domain: span, ceiling: 1, yTicks: yTicks,
            xTicks: [FieldHistoryTick10868(value: span.lower, lines: [clock(Int(span.lower))]),
                     FieldHistoryTick10868(value: span.upper, lines: [clock(Int(span.upper))])],
            guides: [], breaks: [],
            readout: inspecting == nil
                ? .beforeAndRecorded(beforeLabel: "Before awards day", recordedLabel: "Last recorded")
                : .beforeAndInspected(beforeLabel: "Before awards day", inspectedLabel: "Inspected trade"),
            markKey: markKey, comparisonExplanation: nil,
            notes: ["Original Yes trades only · uncaptured intervals stay blank", "Times in UTC (constructed words)"],
            summary: "\(titles[race]!) original Yes trades, zero to one hundred percent, captured contenders only.",
            plotHeight: plotHeight, unboundReadingWords: "Not bound to this trade", plotUnavailableWords: nil,
            windows: windows, scale: nil, moreOriginals: nil, details: nil,
            expand: action("history.expand", "Expand award history"), inspect: nil, previous: nil, next: nil,
            inspection: inspection)
    }

    // MARK: - Owner stories

    private static func reading(_ role: String, _ trade: Trade?, missing: String) -> CeremonyDatedReading10868 {
        guard let trade else { return CeremonyDatedReading10868(role: role, value: .unavailable(words: missing)) }
        return CeremonyDatedReading10868(role: role, value: .recorded(observationID: trade.tx, figure: pct(trade.p),
                                                                       placement: trade.p, date: clock(trade.t)))
    }

    private static func result(_ m: Market) -> String {
        m.race == picture ? (m.winner ? "Won" : "Nominated") : (m.winner ? "Won Best Actor" : "Reported nominee")
    }

    private static func contender(_ m: Market, _ phase: Phase, results: Bool? = nil) -> CeremonyContender10868 {
        let s = m.yes
        let base = baseline(s)
        let earlier: CeremonyDatedReading10868
        let later: CeremonyDatedReading10868
        var separate: CeremonyDatedReading10868?
        if phase == .final {
            earlier = reading("Before awards day", base, missing: "No captured pre-day trade")
            let last = s.trades.last.flatMap { $0.t >= cutoff ? $0 : nil }
            later = reading("Last recorded", last, missing: "No later captured trade")
            if base == nil, let first = s.trades.first {
                separate = reading("First retained · after the pre-day cutoff", first, missing: "No captured trade")
            }
        } else {
            earlier = reading("First retained", s.trades.first { $0.t < cutoff }, missing: "No captured pre-day trade")
            later = reading("Before awards day", base, missing: "No captured pre-day trade")
        }
        return CeremonyContender10868(name: m.name, shape: shapes[m.id]!, tint: tints[m.id]!, earlier: earlier,
                                      later: later, separate: separate,
                                      result: (results ?? (phase == .final)) ? result(m) : nil,
                                      selection: selection(m, "Yes"))
    }

