    /// Every word the page's models put in front of a reader for this input:
    /// headline, history readouts, both stories, the admitted originals'
    /// Details, recorded history, chooser results and side history.
    private static func texts(_ input: CeremonyEventPageInput10868, _ originals: CeremonyEventPageOriginals10868?) -> [String] {
        let model = Model(input)
        var words: [String] = []
        if let headline = model.headline {
            words += [headline.title] + [headline.subtitle, headline.status, headline.eyebrow].compactMap { $0 }
        }
        let history = model.presentedHistory
        for series in history.series {
            for slot in FieldHistoryGeometry10868.readoutSlots(series, in: history) {
                words.append(FieldHistoryGeometry10868.spokenSlot(slot))
            }
        }
        let admitted = model.admitted(originals)
        for card in [Card.points, .bars] {
            guard let story = model.storyModel(card, catalogue: admitted?.catalogue) else { continue }
            words += [story.copy.title, story.spokenGraphic]
        }
        if let admitted {
            if let content = Details.content(catalogue: admitted.catalogue, selection: admitted.selection) {
                words += content.readings.map(\.text) + [content.result?.words].compactMap { $0 }
            }
            if case .recorded(let shown)? = Details.recorded(catalogue: admitted.catalogue, selection: admitted.selection,
                                                             context: admitted.recorded, hasCallback: true) {
                words += [shown.finish?.words, shown.content.result?.words].compactMap { $0 }
            }
            for item in admitted.chooser?.catalogue ?? [] {
                words += [item.result?.words].compactMap { $0 }
            }
            if let side = model.sideHistory(admitted) {
                words += side.series.flatMap { FieldHistoryGeometry10868.readoutSlots($0, in: side).map(FieldHistoryGeometry10868.spokenSlot) }
            }
        }
        return words
    }

    /// A reader intent in plain words, for call logs.
    private static func words(_ intent: CeremonyReaderIntent10868) -> String {
        switch intent {
        case .back: "back"
        case .previous(let card): "previous:\(card.rawValue)"
        case .next(let card): "next:\(card.rawValue)"
        }
    }

    private static func leaks(_ words: [String], _ forbidden: [String]) -> [String] {
        words.filter { text in forbidden.contains { text.contains($0) } }
    }

