    func testTheRetainedCaptureHasTwoCategories84Props168SidesAnd15ReportedNominees() {
        XCTAssertEqual(Tests.digest(Tests.retainedMarkets), "a47efefb430b1f07f9a1f66284a3b8b18cf419de31c42f7740af3d1cfd456714")
        XCTAssertEqual(Tests.markets.count, 84)
        XCTAssertEqual(Tests.race(Tests.picture).count, 42)
        XCTAssertEqual(Tests.race(Tests.actor).count, 42)
        XCTAssertEqual(Tests.markets.flatMap(\.sides).count, 168)
