        XCTAssertEqual(Set(Tests.markets.map(\.condition)).count, 84, "every prop keeps its own condition")
        XCTAssertEqual(Set(Tests.markets.flatMap(\.sides).map(\.token)).count, 168, "every side keeps its own token")
        XCTAssertEqual(Tests.race(Tests.picture).filter(\.nominee).map(\.name),
