    func testTheRetainedTradesAreAll6000StrictOriginalPrintsInSourceOrder() {
        XCTAssertEqual(Tests.digest(Tests.retainedTrades), "6a0fb2a25d5349c488995713d9c6b26e1cec969838f37759931fdefe46e3c36b")
