    func testSameSecondAndIdenticalPrintsStayDistinctTrades() throws {
        func groups(_ s: Side) -> (sameSecond: Int, sameValue: Int) {
            let bySecond = Dictionary(grouping: s.trades, by: \.t).values
            return (bySecond.filter { $0.count > 1 }.count,
                    Dictionary(grouping: s.trades) { "\($0.t) \($0.pText)" }.values.filter { $0.count > 1 }.count)
        }
        let sides = [Tests.oba, Tests.sinners, Tests.chalamet, Tests.jordan].flatMap { Tests.market($0).sides }
        XCTAssertEqual(sides.map { groups($0).sameSecond }, [109, 63, 185, 70, 93, 133, 165, 53])
        XCTAssertEqual(sides.map { groups($0).sameValue }, [64, 44, 101, 31, 53, 103, 145, 36])
        let yes = Tests.market(Tests.oba).yes.trades
        XCTAssertEqual(yes[274].t, yes[275].t)
        XCTAssertEqual(yes[274].pText, "0.8")
        XCTAssertEqual(yes[275].pText, "0.8")
        XCTAssertNotEqual(yes[274].tx, yes[275].tx, "an identical print at the same second is a different trade")
        XCTAssertEqual(yes[68].t, yes[69].t)
        XCTAssertEqual([yes[68].pText, yes[69].pText], ["0.77900014", "0.77"])
        let history = Tests.categoryHistory(Tests.picture, .final)
        let series = try XCTUnwrap(history.series.first)
        for trade in [yes[68], yes[69], yes[274], yes[275]] {
            XCTAssertEqual(FieldHistoryGeometry10868.uniquePoint(trade.tx, in: series)?.x, Double(trade.t),
                           "each print keeps its own owner identity and resolves alone")
        }
        XCTAssertEqual(FieldHistoryGeometry10868.marks(series, in: history).count, yes.count, "no print is merged or dropped")
    }

