        XCTAssertEqual(FieldHistoryGeometry10868.inspectedDisplay(back, in: restored),
                       .figure("76.9%", provenance: "Mar 12, 2026, 19:27:39 UTC"))
        // A duplicated id resolves to nothing.
        var duplicatedRuns = back.runs
        duplicatedRuns.append(FieldHistoryRun10868(id: "copy", points: [FieldHistoryPoint10868(id: held, x: 1_773_400_000, probability: 0.5, style: .filled)]))
        let duplicated = FieldHistorySeries10868(id: back.id, name: back.name, shape: back.shape, tint: back.tint, runs: duplicatedRuns,
                                                 links: [], labelPointID: nil, before: back.before, recorded: back.recorded,
