    func testTheBarsStoryDrawsLightEarlierAndSolidLaterBarsAndKeepsZeroApartFromMissing() throws {
        let model = try XCTUnwrap(Model(Tests.input(.final)).storyModel(.bars, catalogue: Tests.catalogue(.final)))
        let plans = model.plans
        XCTAssertEqual(plans.map(\.contender.name), ["Timothée Chalamet", "Michael B. Jordan"])
        XCTAssertEqual(Geometry.bars(plans[0].slots), [CeremonyBarPlan10868(column: 0, style: .hollow, fraction: 0.32),
                                                       CeremonyBarPlan10868(column: 1, style: .filled, fraction: 0.001)])
        XCTAssertEqual(Geometry.bars(plans[1].slots), [CeremonyBarPlan10868(column: 0, style: .hollow, fraction: nil),
                                                       CeremonyBarPlan10868(column: 1, style: .filled, fraction: 0.999)])
        XCTAssertEqual(Geometry.barOpacity(.hollow), 0.35, "light earlier bar")
        XCTAssertEqual(Geometry.barOpacity(.filled), 1, "solid later bar")
        let rect = CGRect(x: 40, y: 10, width: 200, height: 100)
        let bar = try XCTUnwrap(Geometry.barRect(CeremonyBarPlan10868(column: 0, style: .hollow, fraction: 0.32),
                                                 count: 2, in: rect, maxWidth: 36))
        XCTAssertEqual(bar.minX, 72, accuracy: 1e-9)
        XCTAssertEqual(bar.width, 36, accuracy: 1e-9)
        XCTAssertEqual(bar.minY, 78, accuracy: 1e-9, "rises from the floor to its own placement")
        XCTAssertEqual(bar.maxY, rect.maxY, accuracy: 1e-9)
        XCTAssertNil(Geometry.barRect(CeremonyBarPlan10868(column: 0, style: .hollow, fraction: nil), count: 2, in: rect, maxWidth: 36),
                     "no reading draws no bar — never a zero")
        let zero = try XCTUnwrap(Geometry.barRect(CeremonyBarPlan10868(column: 1, style: .filled, fraction: 0), count: 2, in: rect, maxWidth: 36))
        XCTAssertEqual(zero.height, 0, "a real zero is still a value at the floor")
        XCTAssertEqual(zero.maxY, rect.maxY)
        XCTAssertEqual(Geometry.columnCenter(1, count: 2, in: rect), 190, "each slot keeps its own column")
        XCTAssertNil(Geometry.columnCenter(2, count: 2, in: rect))
    }

