    func testAReadingIsAValueOnlyWithIdFigureDateAndAValidPlacement() {
        func slot(_ value: CeremonyReadingValue10868) -> CeremonyComparisonSlot10868 {
            Geometry.slot(CeremonyDatedReading10868(role: "Before awards day", value: value), style: .hollow, unreadable: "Reading unavailable")
        }
        let valid = slot(.recorded(observationID: "trade-1", figure: "52.7%", placement: 0.527, date: "Mar 15"))
        XCTAssertTrue(valid.isValue)
        XCTAssertEqual(valid.text, "52.7%")
        XCTAssertEqual(valid.date, "Mar 15")
        XCTAssertEqual(valid.placement, 0.527)
        XCTAssertEqual(valid.observationID, "trade-1")
        let broken: [CeremonyReadingValue10868] = [
            .recorded(observationID: "trade-1", figure: "52.7%", placement: 0.527, date: "  "),
            .recorded(observationID: "trade-1", figure: " ", placement: 0.527, date: "Mar 15"),
            .recorded(observationID: "", figure: "52.7%", placement: 0.527, date: "Mar 15"),
            .recorded(observationID: "trade-1", figure: "52.7%", placement: .nan, date: "Mar 15"),
            .recorded(observationID: "trade-1", figure: "52.7%", placement: -0.01, date: "Mar 15"),
            .recorded(observationID: "trade-1", figure: "52.7%", placement: 1.01, date: "Mar 15"),
            .recorded(observationID: "trade-1", figure: "52.7%", placement: .infinity, date: "Mar 15"),
        ]
        for value in broken {
            let shown = slot(value)
            XCTAssertFalse(shown.isValue, "\(value)")
            XCTAssertEqual(shown.text, "Reading unavailable")
            XCTAssertNil(shown.placement, "no mark and no bar")
            XCTAssertNil(shown.date)
            XCTAssertNil(shown.observationID)
            XCTAssertFalse(Geometry.isQualified(value))
        }
        XCTAssertTrue(slot(.recorded(observationID: "z", figure: "0%", placement: 0, date: "Mar 15")).isValue, "a real 0 is a value")
        XCTAssertTrue(slot(.recorded(observationID: "o", figure: "100%", placement: 1, date: "Mar 15")).isValue)
        XCTAssertEqual(slot(.unavailable(words: "No captured pre-day trade")).text, "No captured pre-day trade")
        XCTAssertEqual(slot(.unavailable(words: " ")).text, "Reading unavailable")
    }

    func testOnlyACoherentSameTradeCollapsesAndConflictsStayVisible() throws {
        func reading(_ role: String, _ id: String, _ figure: String, _ placement: Double, _ date: String) -> CeremonyDatedReading10868 {
            CeremonyDatedReading10868(role: role, value: .recorded(observationID: id, figure: figure, placement: placement, date: date))
        }
        let earlier = reading("Before awards day", "trade-9", "32%", 0.32, "Mar 14")
        let coherent = Geometry.slots(earlier: earlier, later: reading("Last recorded", "trade-9", "32%", 0.32, "Mar 14"),
                                      unreadable: "Reading unavailable")
        XCTAssertEqual(coherent.map(\.role), ["Before awards day"], "one coherent trade shows once, under the earlier role")
        XCTAssertEqual(coherent.map(\.style), [.hollow])
        let conflicts = [
            reading("Last recorded", "trade-9", "33%", 0.32, "Mar 14"),
            reading("Last recorded", "trade-9", "32%", 0.33, "Mar 14"),
            reading("Last recorded", "trade-9", "32%", 0.32, "Mar 15"),
            reading("Last recorded", "trade-9", "32%", 0.32, " "),
            reading("Last recorded", "trade-9", "32%", .nan, "Mar 14"),
        ]
        for later in conflicts {
            let shown = Geometry.slots(earlier: earlier, later: later, unreadable: "Reading unavailable")
            XCTAssertEqual(shown.count, 2, "a conflicting or invalid reading under one id is never hidden: \(later)")
            XCTAssertFalse(Geometry.sameTrade(earlier, later))
        }
        let distinct = Geometry.slots(earlier: earlier, later: reading("Last recorded", "trade-10", "32%", 0.32, "Mar 14"),
                                      unreadable: "Reading unavailable")
        XCTAssertEqual(distinct.map(\.observationID), ["trade-9", "trade-10"], "equal figure and date, different trades: both stay")
        let jordan = try XCTUnwrap(Model(Tests.input(.final)).storyModel(.bars, catalogue: Tests.catalogue(.final))).plans[1]
        XCTAssertEqual(jordan.slots.count, 2)
        XCTAssertNotNil(jordan.separate, "Jordan's first retained reading stays separate")
    }

