    func testDetailsRecordedHistoryHandsBackExactIntentsAndUncapturedSidesStayReachable() throws {
        var log: [String] = []
        let m = Tests.market(Tests.oba)
        let held = Tests.selection(m, "No")
        let bundle = Tests.originals(.final, held: held)
        guard case .recorded(let shown)? = Details.recorded(catalogue: bundle.catalogue, selection: held,
                                                             context: bundle.recorded, hasCallback: true) else {
            return XCTFail("the No original's own recorded history")
        }
        XCTAssertEqual(shown.history.series.map(\.id), ["613835-No"])
        XCTAssertEqual(shown.content.readings.map(\.label), ["Before awards day", "Last recorded"])
        XCTAssertEqual(shown.content.readings.map(\.text), ["23.9%", "0.1%"])
        XCTAssertTrue(shown.showsPlot)
        let intent = try XCTUnwrap(Details.intent(.expand, in: shown))
        XCTAssertEqual(intent, Details.HistoryIntent(selection: held, entry: .expand, actionID: "original.expand"))
        let page = Page(input: Tests.input(.final), mode: .original, originals: bundle,
                        onOriginalHistory: { log.append("history:\($0.selection.identity.side):\($0.actionID)") },
                        onInteraction: { log.append("hold") })
        page.originalDetailsContent()?.onHistory?(intent)
        XCTAssertEqual(log, ["hold", "history:No:original.expand"])
        var reachable = 0
        for market in Tests.markets {
            for side in market.sides where !side.captured {
                let selection = Tests.selection(market, side.side)
                let context = Tests.recorded(market, side, .final)
                guard case .recorded(let uncaptured)? = Details.recorded(catalogue: Tests.catalogue(.final), selection: selection,
                                                                         context: context, hasCallback: true) else {
                    XCTFail("\(market.name) \(side.side) Details"); continue
                }
                XCTAssertFalse(uncaptured.showsPlot, "absent history is said, never drawn as zero")
                XCTAssertNil(uncaptured.expand)
                reachable += 1
            }
        }
        XCTAssertEqual(reachable, 160)
    }

    func testTheReportedAwardResultStaysApartFromTheOriginalGrade() throws {
        func shown(_ id: String, _ side: String, _ phase: Phase) -> Details.RecordedShown? {
            let m = Tests.market(id)
