    /// Each surface fails its own assertion if it read the raw bundle.
    private func assertNoOriginalsSurface(page phase: Phase, bundle: Phase) throws {
        let raw = Tests.fullOriginals(bundle)
        var log: [String] = []
        let page = Page(input: Tests.input(phase), originals: raw,
                        onCatalogue: { log.append("catalogue") }, onCatalogueChoose: { _ in log.append("choose") },
                        onSide: { _ in log.append("side") }, onOriginalHistory: { _ in log.append("history") },
                        onSideHistoryAction: { _ in log.append("sideHistory") }, onStoryOpen: { _ in log.append("open") },
                        onReaderIntent: { log.append("reader:" + Tests.words($0)) })
        XCTAssertTrue(page.model.originalsAreForAnotherPhase(raw))
        XCTAssertNil(page.admittedOriginals)
        XCTAssertNil(page.chooserContent(), "chooser")
        XCTAssertNil(page.catalogueAction, "all-originals entry")
        XCTAssertNil(page.sideChoicesContent(), "side choices")
        XCTAssertNil(page.originalDetailsContent(), "Details")
        XCTAssertNil(page.originalDetailsContent()?.recorded, "recorded history")
        XCTAssertNil(page.sideHistoryContent(), "side history and its actions")
        if let story = page.pagePointsContent() {
            XCTAssertNil(story.model.plans[0].opens, "story open")
            XCTAssertNil(story.model.openAction(story.model.plans[0], story.onOpen))
            XCTAssertTrue(story.model.originalIsUnavailable(story.model.plans[0]))
        }
        XCTAssertEqual(Tests.leaks(Tests.texts(Tests.input(phase), raw), ["Happened", "Didn't happen", "Winner"]).count,
                       phase == .final ? Tests.leaks(Tests.texts(Tests.input(phase), nil), ["Happened", "Didn't happen", "Winner"]).count : 0,
                       "no grade or award fact from the other phase's bundle")
        page.sideHistoryBack?()
        XCTAssertEqual(log, ["reader:back"], "Back stays available; nothing else acts")
    }

