    func testAHeldReaderOrderIsIndependentOfAReRankedStream() {
        let order: [Card] = [.points, .bars, .history]
        let first = Model(Tests.input(.final, stream: Tests.stream(.final), readerOrder: order))
        let reranked = Model(Tests.input(.final, stream: Tests.stream(.final, pointsFirst: false), readerOrder: order))
        XCTAssertEqual(first.readerSequence, reranked.readerSequence)
        XCTAssertEqual(reranked.neighbour(of: .points, offset: 1), .bars)
        XCTAssertNil(reranked.neighbour(of: .points, offset: -1))
    }

    func testAnEmptyAbsentUnmountedOrDuplicatedReaderEntryOffersNoNeighbour() {
        XCTAssertNil(Model(Tests.input(.final, readerOrder: [])).neighbour(of: .history, offset: 1), "an empty order offers none")
        let absent = Model(Tests.input(.final, readerOrder: [.history, .bars]))
        XCTAssertNil(absent.neighbour(of: .points, offset: 1), "an absent card has no position")
        XCTAssertEqual(absent.neighbour(of: .history, offset: 1), .bars)
        let unmounted = Model(Tests.input(.final, readerOrder: [.history, .points, .bars], withoutPoints: true))
        XCTAssertNil(unmounted.neighbour(of: .history, offset: 1), "nothing skips past an unmounted entry")
        XCTAssertNil(unmounted.neighbour(of: .bars, offset: -1))
        let duplicated = Model(Tests.input(.final, readerOrder: [.history, .points, .points, .bars]))
        XCTAssertNil(duplicated.neighbour(of: .history, offset: 1), "a duplicated entry is ambiguous")
        XCTAssertNil(duplicated.neighbour(of: .points, offset: 1))
        XCTAssertNil(Model.uniqueIndex(of: .points, in: [.history, .points, .points]))
    }

    func testTheReaderShowsTheSameStoryModelsAndOwnerWordsForAnUnmountedCard() throws {
        let bundle = Tests.fullOriginals(.final)
        let page = Page(input: Tests.input(.final), originals: bundle)
        XCTAssertEqual(Page(input: Tests.input(.final), mode: .reader(.points), originals: bundle).readerPointsContent()?.model,
                       page.pagePointsContent()?.model, "same story content inline and full size")
        XCTAssertEqual(Page(input: Tests.input(.final), mode: .reader(.bars), originals: bundle).readerBarsContent()?.model,
                       page.pageBarsContent()?.model)
        XCTAssertNil(Page(input: Tests.input(.final, withoutBars: true), mode: .reader(.bars)).readerBarsContent())
        XCTAssertFalse(Model(Tests.input(.final, withoutBars: true)).isMounted(.bars))
        XCTAssertEqual(Tests.copy.readerUnavailable, "This card is not available now")
    }

    // MARK: - Layout, targets and axis labels (Design A3)

    func testLayoutPlansStackOnPhonesAndAccessibilitySizes() {
        XCTAssertEqual(RugbyMatchEventPageModel10868.arrangements(sizeClass: .compact, accessibilitySize: false), [.stacked])
        XCTAssertEqual(RugbyMatchEventPageModel10868.arrangements(sizeClass: .regular, accessibilitySize: false), [.sideBySide, .stacked])
        XCTAssertEqual(RugbyMatchEventPageModel10868.arrangements(sizeClass: nil, accessibilitySize: false), [.sideBySide, .stacked])
        XCTAssertEqual(RugbyMatchEventPageModel10868.arrangements(sizeClass: .regular, accessibilitySize: true), [.stacked])
        XCTAssertEqual(Model.readingArrangements(accessibilitySize: true), [.stacked])
        XCTAssertEqual(Model.readingArrangements(accessibilitySize: false), [.sideBySide, .stacked])
        XCTAssertEqual(Model.readingOrder, [.headline, .notice, .choices, .anchor, .update, .stories, .catalogue])
        XCTAssertGreaterThan(Model.sortPriority(.headline), Model.sortPriority(.anchor))
        XCTAssertGreaterThan(Model.sortPriority(.anchor), Model.sortPriority(.stories))
    }

    func testEveryControlTargetIsAtLeastTheMinimum() {
        XCTAssertEqual(EsportsEventPageModel10868.minimumTarget, 44)
        XCTAssertEqual(EsportsEventPageModel10868.targetHeight(.nan), 44)
        #if canImport(UIKit)
        let metrics = UIFontMetrics(forTextStyle: .body)
        func scaled(_ size: UIContentSizeCategory) -> CGFloat {
            metrics.scaledValue(for: 44, compatibleWith: UITraitCollection(preferredContentSizeCategory: size))
        }
        XCTAssertLessThan(scaled(.extraSmall), 44, "control: the scaled metric alone would shrink below the minimum")
        XCTAssertEqual(EsportsEventPageModel10868.targetHeight(scaled(.extraSmall)), 44)
        XCTAssertEqual(EsportsEventPageModel10868.targetHeight(scaled(.accessibilityExtraExtraExtraLarge)),
                       scaled(.accessibilityExtraExtraExtraLarge))
        #endif
    }

    func testBarAxisLabelsStayWholeAtOrdinaryXXXLAndAX3() {
        var heights: [CGFloat] = [13.1, 20.3, 33.4]
        var plots: [CGFloat] = [120, 160, 276]
        #if canImport(UIKit)
        let sizes: [UIContentSizeCategory] = [.large, .extraExtraExtraLarge, .accessibilityExtraExtraExtraLarge]
        heights = sizes.map {
            UIFont.preferredFont(forTextStyle: .caption2, compatibleWith: UITraitCollection(preferredContentSizeCategory: $0)).lineHeight
        }
        plots = sizes.map {
            UIFontMetrics(forTextStyle: .body).scaledValue(for: 120, compatibleWith: UITraitCollection(preferredContentSizeCategory: $0))
        }
        #endif
        for (height, plotHeight) in zip(heights, plots) {
            let canvas = CGSize(width: 300, height: plotHeight)
            let label = CGSize(width: height * 2.4, height: height)
            let plot = Geometry.barPlotRect(in: canvas, label: label, minimumLeading: 44)
            XCTAssertGreaterThan(plot.height, 0)
            XCTAssertEqual(Geometry.y(0, in: plot), plot.maxY, accuracy: 1e-9, "common 0–100%: 0 at the floor")
            XCTAssertEqual(Geometry.y(1, in: plot), plot.minY, accuracy: 1e-9)
            for value in [0.0, 0.5, 1.0] {
                let frame = Geometry.axisLabelFrame(value, label: label, plot: plot)
                XCTAssertGreaterThanOrEqual(frame.minY, 0, "label \(value) whole at the top, line \(height)")
                XCTAssertLessThanOrEqual(frame.maxY, canvas.height, "label \(value) whole at the bottom, line \(height)")
                XCTAssertGreaterThanOrEqual(frame.minX, 0)
                XCTAssertEqual(frame.height, height, "never shrunk")
            }
        }
        // Control: the earlier fixed 8 pt inset would cut the floor label at the larger sizes.
        let old = CGRect(x: 44, y: 8, width: 252, height: plots[2] - 12)
        XCTAssertGreaterThan(old.maxY + heights[2] / 2, plots[2], "positive control for the fixed-inset defect")
    }

    func testPointAxisLabelsKeepTheirMeasuredSizeAndStayInside() {
        let track = CGRect(x: 11, y: 0, width: 278, height: 0)
        let bounds = CGRect(x: 0, y: 0, width: 300, height: 20)
        XCTAssertEqual(Geometry.labelOrigin(0, width: 30, track: track, bounds: bounds), 11, "leading edge at 0%")
        XCTAssertEqual(Geometry.labelOrigin(1, width: 40, track: track, bounds: bounds), 249, "trailing edge at 100%")
        XCTAssertEqual(Geometry.labelOrigin(0.5, width: 30, track: track, bounds: bounds), 135, "centred at the middle")
        XCTAssertEqual(Geometry.labelOrigin(1, width: 320, track: track, bounds: bounds), 0, "kept inside the bounds")
        #if canImport(UIKit)
        for size in [DynamicTypeSize.large, .xxxLarge, .accessibility3] {
            let labels = CeremonyAxisLabelsLayout10868(values: [0, 0.5, 1], inset: 11) {
                Text("0%").font(.caption2).fixedSize()
                Text("50%").font(.caption2).fixedSize()
                Text("100%").font(.caption2).fixedSize()
            }
            let host = hostForMeasurement(labels, at: size)
            let fitted = host.sizeThatFits(in: CGSize(width: 300, height: CGFloat.greatestFiniteMagnitude))
            XCTAssertTrue(fitted.height.isFinite)
            XCTAssertGreaterThan(fitted.height, 10, "\(size): the labels' own measured height is reserved")
        }
        #endif
    }

    func testThePageAndEveryModeHaveAFiniteHeightAtPhoneWideAndAccessibilitySizes() {
        #if canImport(UIKit)
        let bundle = Tests.fullOriginals(.final)
        let modes: [CeremonyEventPageMode10868] = [.page, .reader(.history), .reader(.points), .reader(.bars), .catalogue,
                                                   .original, .sideHistory, .about]
        for width in [CGFloat(375), 393, 1024] {
            for size in [DynamicTypeSize.large, .xxxLarge, .accessibility3] {
                for mode in modes {
                    let page = Page(input: Tests.input(.final), mode: mode, originals: bundle, onAbout: {}, onCatalogue: {},
                                    onStoryOpen: { _ in }, onReaderIntent: { _ in })
                    let host = hostForMeasurement(page, at: size)
                    let fitted = host.sizeThatFits(in: CGSize(width: width, height: CGFloat.greatestFiniteMagnitude))
                    XCTAssertTrue(fitted.height.isFinite && fitted.height > 0, "\(mode) at \(width) / \(size)")
                }
            }
        }
        #endif
    }
